update public.question_bank set question = $q${"form":"bai_tap","type":"true_false","topic":"Các công thức của chuyển động thẳng biến đổi đều","question":"<p class=\"text-base leading-relaxed my-2\">Một ô tô đang chạy với tốc độ $54km/h$ trên đoạn đường thẳng thì người lái xe hãm phanh cho ô tô chạy thẳng chậm dần đều. Sau khi chạy thêm $250 m$ thì tốc độ của ô tô chỉ còn $5 m/s.$</p>","difficulty":"trung-binh","statements":[{"text":"Độ dịch chuyển của ô tô là 250 m.","answer":true},{"text":"Ô tô từ khi hãm phanh chuyển động với gia tốc 0,4 m/s$^{2}$.","answer":true},{"text":"Thời gian ô tô chạy thêm được 250 m kể từ khi bắt đầu hãm phanh là 25 giay.","answer":true},{"text":"Từ lúc bắt đầu hàm phanh đến khi dừng hẳn mắt 35 giây.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi $v_0 = 54$ km/h $= 15$ m/s. Ô tô chuyển động thẳng chậm dần đều, chọn chiều dương là chiều chuyển động.</p><p class=\"text-base leading-relaxed my-2\">$v^2 - v_0^2 = 2as$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = \\dfrac{5^2 - 15^2}{2\\cdot 250} = -0{,}4$ m/s²</p><p class=\"text-base leading-relaxed my-2\">$t = \\dfrac{v - v_0}{a} = \\dfrac{5-15}{-0{,}4} = 25$ s</p><p class=\"text-base leading-relaxed my-2\">$t' = \\dfrac{0 - v_0}{a} = \\dfrac{-15}{-0{,}4} = 37{,}5$ s</p><p class=\"text-base leading-relaxed my-2\">a) Xe chuyển động thẳng theo một chiều nên độ dịch chuyển $d = 250$ m. Ý a Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Gia tốc có độ lớn $0{,}4$ m/s² ($a=-0{,}4$ m/s² do chậm dần). Ý b Đúng.</p><p class=\"text-base leading-relaxed my-2\">c) $t = 25$ s. Ý c Đúng.</p><p class=\"text-base leading-relaxed my-2\">d) Thời gian đến khi dừng hẳn là $37{,}5$ s, không phải $35$ s. Ý d Sai.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"true_false","topic":"Các công thức của chuyển động thẳng biến đổi đều","question":"<p class=\"text-base leading-relaxed my-2\">Một ô tô đang chạy với tốc độ $54km/h$ trên đoạn đường thẳng thì người lái xe hãm phanh cho ô tô chạy thẳng chậm dần đều. Sau khi chạy thêm $250 m$ thì tốc độ của ô tô chỉ còn $5 m/s.$</p>","difficulty":"trung-binh","statements":[{"text":"Độ dịch chuyển của ô tô là 250 m.","answer":true},{"text":"Ô tô từ khi hãm phanh chuyển động với gia tốc 0,4 m/s$^{2}$.","answer":true},{"text":"Thời gian ô tô chạy thêm được 250 m kể từ khi bắt đầu hãm phanh là 25 giay.","answer":true},{"text":"Từ lúc bắt đầu hàm phanh đến khi dừng hẳn mắt 35 giây.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi $v_0 = 54$ km/h $= 15$ m/s. Ô tô chuyển động thẳng chậm dần đều, chọn chiều dương là chiều chuyển động.</p><p class=\"text-base leading-relaxed my-2\">$v^2 - v_0^2 = 2as$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow a = \\dfrac{5^2 - 15^2}{2\\cdot 250} = -0{,}4$ m/s²</p><p class=\"text-base leading-relaxed my-2\">$t = \\dfrac{v - v_0}{a} = \\dfrac{5-15}{-0{,}4} = 25$ s</p><p class=\"text-base leading-relaxed my-2\">$t' = \\dfrac{0 - v_0}{a} = \\dfrac{-15}{-0{,}4} = 37{,}5$ s</p><p class=\"text-base leading-relaxed my-2\">a) Xe chuyển động thẳng theo một chiều nên độ dịch chuyển $d = 250$ m. Ý a Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Gia tốc có độ lớn $0{,}4$ m/s² ($a=-0{,}4$ m/s² do chậm dần). Ý b Đúng.</p><p class=\"text-base leading-relaxed my-2\">c) $t = 25$ s. Ý c Đúng.</p><p class=\"text-base leading-relaxed my-2\">d) Thời gian đến khi dừng hẳn là $37{,}5$ s, không phải $35$ s. Ý d Sai.</p>","difficultySource":"ai"}$q$::jsonb), archived = false, updated_at = now() where id = 1544378 and note = 'nap-vl10-c2-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"true_false","topic":"Các công thức của chuyển động thẳng biến đổi đều","question":"<p class=\"text-base leading-relaxed my-2\">Phương trình cơ bản của 1 vật chuyển động $x=6t^{2}–18t+12\\left( cm \\right)$.</p>","difficulty":"trung-binh","statements":[{"text":"Vận tốc ban đầu của xe là 18 cm/s.","answer":false},{"text":"Xe chuyển động chậm dần với gia tốc 12 cm/s$^{2}$.","answer":false},{"text":"Lúc t = 2 s thì vận tốc của xe là 8 cm/s.","answer":false},{"text":"Toạ độ của vật khi vận tốc đạt 36 cm/s là 525 mm.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">So sánh với $x=x_0+v_0t+\\frac{1}{2}at^2$: $x_0=12$ cm, $v_0=-18$ cm/s, $a=12$ cm/s².</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=-18+12t$ (cm/s).</p><p class=\"text-base leading-relaxed my-2\">a) $v_0=-18$ cm/s (ngược chiều dương), không phải 18 cm/s. Sai.</p><p class=\"text-base leading-relaxed my-2\">b) Gia tốc $a=12$ cm/s² nhưng vật chỉ chậm dần khi $0\\lt t\\lt 1{,}5$ s ($v$ và $a$ trái dấu), sau đó nhanh dần. Kết luận chung \"chuyển động chậm dần\" là Sai.</p><p class=\"text-base leading-relaxed my-2\">c) $t=2$ s: $v=-18+12\\cdot2=6$ cm/s $\\neq 8$ cm/s. Sai.</p><p class=\"text-base leading-relaxed my-2\">d) $v=36$: $-18+12t=36$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=4{,}5$ s</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x=6\\cdot4{,}5^2-18\\cdot4{,}5+12=52{,}5$ cm $=525$ mm. Đúng.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"true_false","topic":"Các công thức của chuyển động thẳng biến đổi đều","question":"<p class=\"text-base leading-relaxed my-2\">Phương trình cơ bản của 1 vật chuyển động $x=6t^{2}–18t+12\\left( cm \\right)$.</p>","difficulty":"trung-binh","statements":[{"text":"Vận tốc ban đầu của xe là 18 cm/s.","answer":false},{"text":"Xe chuyển động chậm dần với gia tốc 12 cm/s$^{2}$.","answer":false},{"text":"Lúc t = 2 s thì vận tốc của xe là 8 cm/s.","answer":false},{"text":"Toạ độ của vật khi vận tốc đạt 36 cm/s là 525 mm.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">So sánh với $x=x_0+v_0t+\\frac{1}{2}at^2$: $x_0=12$ cm, $v_0=-18$ cm/s, $a=12$ cm/s².</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=-18+12t$ (cm/s).</p><p class=\"text-base leading-relaxed my-2\">a) $v_0=-18$ cm/s (ngược chiều dương), không phải 18 cm/s. Sai.</p><p class=\"text-base leading-relaxed my-2\">b) Gia tốc $a=12$ cm/s² nhưng vật chỉ chậm dần khi $0\\lt t\\lt 1{,}5$ s ($v$ và $a$ trái dấu), sau đó nhanh dần. Kết luận chung \"chuyển động chậm dần\" là Sai.</p><p class=\"text-base leading-relaxed my-2\">c) $t=2$ s: $v=-18+12\\cdot2=6$ cm/s $\\neq 8$ cm/s. Sai.</p><p class=\"text-base leading-relaxed my-2\">d) $v=36$: $-18+12t=36$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=4{,}5$ s</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x=6\\cdot4{,}5^2-18\\cdot4{,}5+12=52{,}5$ cm $=525$ mm. Đúng.</p>","difficultySource":"ai"}$q$::jsonb), archived = false, updated_at = now() where id = 1544387 and note = 'nap-vl10-c2-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"true_false","topic":"Khái niệm gia tốc và đồ thị vận tốc – thời gian","question":"<p class=\"text-base leading-relaxed my-2\">Cho đồ thị vận tốc – thời gian của một vật chuyển động thẳng như hình vẽ. Biết ban đầu vật có tọa độ 15m.</p>","difficulty":"kho","statements":[{"text":"Xe chuyển động nhanh dần trong 4 giây đầu và chuyển động chậm dần trong 4 giây sau đó.","answer":true},{"text":"Gia tốc của xe đi được từ giây thứ 2 đến giây thứ 4 là 7,5 m/s$^{2}$.","answer":true},{"text":"Trong 8 giây xe đi được quãng đường 75 m với tốc độ trung bình là 9,375 m/s.","answer":true},{"text":"Phương trình dao động của xe trong 4 giây cuối là $x_{3}=25+5t+3,75t^{2}\\left( 4\\leq t\\leq8 \\right)$","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Đồ thị cho thấy vận tốc tăng trong 4 s đầu (chuyển động nhanh dần) và giảm trong 4 s sau (chuyển động chậm dần). Ý này <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">b) Gia tốc trong khoảng từ giây thứ 2 đến giây thứ 4 là $a=\\dfrac{\\Delta v}{\\Delta t}=7{,}5\\ \\text{m/s}^2$. Ý này <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">c) Quãng đường bằng diện tích dưới đồ thị, $s = 75$ m. Tốc độ trung bình là $v_{tb}=\\dfrac{s}{t}=\\dfrac{75}{8}=9{,}375$ m/s. Ý này <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">d) Phương trình $x_3=25+5t+3{,}75t^2$ có hệ số $\\tfrac12 a=3{,}75$ nên $a=+7{,}5\\ \\text{m/s}^2$, cùng dấu với vận tốc đầu $v_0=5$ m/s. Như vậy xe chuyển động nhanh dần trong 4 s cuối. Điều này mâu thuẫn với đồ thị, vì trong 4 s cuối xe chuyển động chậm dần. Ý này <b>Sai</b>.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"true_false","topic":"Khái niệm gia tốc và đồ thị vận tốc – thời gian","question":"<p class=\"text-base leading-relaxed my-2\">Cho đồ thị vận tốc – thời gian của một vật chuyển động thẳng như hình vẽ. Biết ban đầu vật có tọa độ 15m.</p>","difficulty":"kho","statements":[{"text":"Xe chuyển động nhanh dần trong 4 giây đầu và chuyển động chậm dần trong 4 giây sau đó.","answer":true},{"text":"Gia tốc của xe đi được từ giây thứ 2 đến giây thứ 4 là 7,5 m/s$^{2}$.","answer":true},{"text":"Trong 8 giây xe đi được quãng đường 75 m với tốc độ trung bình là 9,375 m/s.","answer":true},{"text":"Phương trình dao động của xe trong 4 giây cuối là $x_{3}=25+5t+3,75t^{2}\\left( 4\\leq t\\leq8 \\right)$","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Đồ thị cho thấy vận tốc tăng trong 4 s đầu (chuyển động nhanh dần) và giảm trong 4 s sau (chuyển động chậm dần). Ý này <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">b) Gia tốc trong khoảng từ giây thứ 2 đến giây thứ 4 là $a=\\dfrac{\\Delta v}{\\Delta t}=7{,}5\\ \\text{m/s}^2$. Ý này <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">c) Quãng đường bằng diện tích dưới đồ thị, $s = 75$ m. Tốc độ trung bình là $v_{tb}=\\dfrac{s}{t}=\\dfrac{75}{8}=9{,}375$ m/s. Ý này <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">d) Phương trình $x_3=25+5t+3{,}75t^2$ có hệ số $\\tfrac12 a=3{,}75$ nên $a=+7{,}5\\ \\text{m/s}^2$, cùng dấu với vận tốc đầu $v_0=5$ m/s. Như vậy xe chuyển động nhanh dần trong 4 s cuối. Điều này mâu thuẫn với đồ thị, vì trong 4 s cuối xe chuyển động chậm dần. Ý này <b>Sai</b>.</p>","difficultySource":"ai"}$q$::jsonb), archived = false, updated_at = now() where id = 1544394 and note = 'nap-vl10-c2-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"true_false","topic":"Tính thời gian, quãng đường, vận tốc khi rơi tự do","question":"<p class=\"text-base leading-relaxed my-2\">Từ đỉnh tháp cao $20 m,$ người ta buông một vật. Sau $2 s,$ thì người ta lại buông vật thứ 2 ở tầng thấp hơn đỉnh tháp$5 m.$ Chọn trục Oy thẳng đứng, gốc O ở đỉnh tháp, chiều dương hướng xuống, thời gian lúc vật 1 bắt đầu rơi, lấy$g=10 m/s^{2}.$</p>","difficulty":"trung-binh","statements":[{"text":"Phương trình chuyển động của vật 2 là$x_{2}=5+5t^{2}\\left( m \\right).$","answer":false},{"text":"Vận tốc chạm đất của vật 1 là 17 m/s.","answer":false},{"text":"Vật 2 chạm đất mất hết 1,73 giây.","answer":true},{"text":"Vận tốc chạm đất của vật 1 nhỏ hơn của vật 2.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn O ở đỉnh tháp, chiều dương hướng xuống, mặt đất ở $y=20$ m. Vật 1: $y_1=5t^2$. Vật 2 buông sau 2 s tại $y=5$ m, không vận tốc đầu: $y_2=5+5(t-2)^2$ với $t\\ge 2$ s.</p><p class=\"text-base leading-relaxed my-2\">a) Phương trình đúng của vật 2 là $y_2=5+5(t-2)^2$, không phải $5+5t^2$</p><p class=\"text-base leading-relaxed my-2\">⇒ Sai.</p><p class=\"text-base leading-relaxed my-2\">b) Vật 1 chạm đất khi $5t^2=20$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=2$ s</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v_1=gt=20$ m/s, khác 17 m/s</p><p class=\"text-base leading-relaxed my-2\">⇒ Sai.</p><p class=\"text-base leading-relaxed my-2\">c) Vật 2 rơi quãng đường 15 m: $15=5\\tau^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\tau=\\sqrt3\\approx1{,}73$ s (tính từ lúc buông vật 2)</p><p class=\"text-base leading-relaxed my-2\">⇒ Đúng.</p><p class=\"text-base leading-relaxed my-2\">d) $v_2=g\\tau\\approx17{,}3$ m/s $\\lt v_1=20$ m/s, nên vận tốc chạm đất của vật 1 lớn hơn vật 2</p><p class=\"text-base leading-relaxed my-2\">⇒ Sai.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"true_false","topic":"Tính thời gian, quãng đường, vận tốc khi rơi tự do","question":"<p class=\"text-base leading-relaxed my-2\">Từ đỉnh tháp cao $20 m,$ người ta buông một vật. Sau $2 s,$ thì người ta lại buông vật thứ 2 ở tầng thấp hơn đỉnh tháp$5 m.$ Chọn trục Oy thẳng đứng, gốc O ở đỉnh tháp, chiều dương hướng xuống, thời gian lúc vật 1 bắt đầu rơi, lấy$g=10 m/s^{2}.$</p>","difficulty":"trung-binh","statements":[{"text":"Phương trình chuyển động của vật 2 là$x_{2}=5+5t^{2}\\left( m \\right).$","answer":false},{"text":"Vận tốc chạm đất của vật 1 là 17 m/s.","answer":false},{"text":"Vật 2 chạm đất mất hết 1,73 giây.","answer":true},{"text":"Vận tốc chạm đất của vật 1 nhỏ hơn của vật 2.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn O ở đỉnh tháp, chiều dương hướng xuống, mặt đất ở $y=20$ m. Vật 1: $y_1=5t^2$. Vật 2 buông sau 2 s tại $y=5$ m, không vận tốc đầu: $y_2=5+5(t-2)^2$ với $t\\ge 2$ s.</p><p class=\"text-base leading-relaxed my-2\">a) Phương trình đúng của vật 2 là $y_2=5+5(t-2)^2$, không phải $5+5t^2$</p><p class=\"text-base leading-relaxed my-2\">⇒ Sai.</p><p class=\"text-base leading-relaxed my-2\">b) Vật 1 chạm đất khi $5t^2=20$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=2$ s</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v_1=gt=20$ m/s, khác 17 m/s</p><p class=\"text-base leading-relaxed my-2\">⇒ Sai.</p><p class=\"text-base leading-relaxed my-2\">c) Vật 2 rơi quãng đường 15 m: $15=5\\tau^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\tau=\\sqrt3\\approx1{,}73$ s (tính từ lúc buông vật 2)</p><p class=\"text-base leading-relaxed my-2\">⇒ Đúng.</p><p class=\"text-base leading-relaxed my-2\">d) $v_2=g\\tau\\approx17{,}3$ m/s $\\lt v_1=20$ m/s, nên vận tốc chạm đất của vật 1 lớn hơn vật 2</p><p class=\"text-base leading-relaxed my-2\">⇒ Sai.</p>","difficultySource":"ai"}$q$::jsonb), archived = false, updated_at = now() where id = 1544501 and note = 'nap-vl10-c2-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"true_false","topic":"Phân tích chuyển động ném ngang theo hai phương","question":"<p class=\"text-base leading-relaxed my-2\">Một vật được ném theo phương nằm ngang từ độ cao $5 m$ so với mặt đất, có tầm xa trên mặt đất $ L = 10\\sqrt{3} m.$ Bỏ qua sức cản của không khí. Lấy $ g = 10 m/s^{2}.$</p>","difficulty":"trung-binh","statements":[{"text":"Vận tốc ban đầu của vật là 10$\\sqrt{3}$ m/s.","answer":true},{"text":"Vận tốc của vật ngay trước khi chạm đất đạt 20$\\sqrt{3}$ m/s.","answer":false},{"text":"Khi chạm đất vận tốc của vật hợp với phương ngang 1 góc 30$^{0}$.","answer":true},{"text":"Khoảng cách từ vị trí ném vật đến nơi vật chạm đất là","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn gốc tại vị trí ném, Ox nằm ngang theo hướng ném, Oy thẳng đứng hướng xuống. Ném ngang gồm chuyển động đều theo Ox và rơi tự do theo Oy.</p><p class=\"text-base leading-relaxed my-2\">Thời gian rơi: $t=\\sqrt{\\dfrac{2h}{g}}=\\sqrt{\\dfrac{2\\cdot5}{10}}=1$ s.</p><p class=\"text-base leading-relaxed my-2\">a) $v_0=\\dfrac{L}{t}=10\\sqrt3$ m/s. Ý a <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">b) $v_x=10\\sqrt3$ m/s, $v_y=gt=10$ m/s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=\\sqrt{v_x^2+v_y^2}=\\sqrt{300+100}=20$ m/s, khác $20\\sqrt3$ m/s. Ý b <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">c) $\\tan\\alpha=\\dfrac{v_y}{v_x}=\\dfrac{10}{10\\sqrt3}=\\dfrac{1}{\\sqrt3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha=30^\\circ$. Ý c <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">d) Khoảng cách từ vị trí ném đến nơi chạm đất: $d=\\sqrt{L^2+h^2}=\\sqrt{300+25}=5\\sqrt{13}\\approx18{,}03$ m, không bằng $10\\sqrt3$ m (tầm xa). Ý d <b>Sai</b> (đề cụt nội dung, xét theo khoảng cách đường thẳng).</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"true_false","topic":"Phân tích chuyển động ném ngang theo hai phương","question":"<p class=\"text-base leading-relaxed my-2\">Một vật được ném theo phương nằm ngang từ độ cao $5 m$ so với mặt đất, có tầm xa trên mặt đất $ L = 10\\sqrt{3} m.$ Bỏ qua sức cản của không khí. Lấy $ g = 10 m/s^{2}.$</p>","difficulty":"trung-binh","statements":[{"text":"Vận tốc ban đầu của vật là 10$\\sqrt{3}$ m/s.","answer":true},{"text":"Vận tốc của vật ngay trước khi chạm đất đạt 20$\\sqrt{3}$ m/s.","answer":false},{"text":"Khi chạm đất vận tốc của vật hợp với phương ngang 1 góc 30$^{0}$.","answer":true},{"text":"Khoảng cách từ vị trí ném vật đến nơi vật chạm đất là","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn gốc tại vị trí ném, Ox nằm ngang theo hướng ném, Oy thẳng đứng hướng xuống. Ném ngang gồm chuyển động đều theo Ox và rơi tự do theo Oy.</p><p class=\"text-base leading-relaxed my-2\">Thời gian rơi: $t=\\sqrt{\\dfrac{2h}{g}}=\\sqrt{\\dfrac{2\\cdot5}{10}}=1$ s.</p><p class=\"text-base leading-relaxed my-2\">a) $v_0=\\dfrac{L}{t}=10\\sqrt3$ m/s. Ý a <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">b) $v_x=10\\sqrt3$ m/s, $v_y=gt=10$ m/s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=\\sqrt{v_x^2+v_y^2}=\\sqrt{300+100}=20$ m/s, khác $20\\sqrt3$ m/s. Ý b <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">c) $\\tan\\alpha=\\dfrac{v_y}{v_x}=\\dfrac{10}{10\\sqrt3}=\\dfrac{1}{\\sqrt3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha=30^\\circ$. Ý c <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">d) Khoảng cách từ vị trí ném đến nơi chạm đất: $d=\\sqrt{L^2+h^2}=\\sqrt{300+25}=5\\sqrt{13}\\approx18{,}03$ m, không bằng $10\\sqrt3$ m (tầm xa). Ý d <b>Sai</b> (đề cụt nội dung, xét theo khoảng cách đường thẳng).</p>","difficultySource":"ai"}$q$::jsonb), archived = false, updated_at = now() where id = 1544581 and note = 'nap-vl10-c2-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Phân tích chuyển động ném ngang theo hai phương","answer":2,"options":["Chuyển động ném ngang có thể được phân tích thành hai chuyển động thành phần chuyển động theo quán tính ở độ cao không đổi và chuyển động rơi tự do.","Vận tốc ban đầu và chiều cao ban đầu càng lớn thì tầm ném xa càng lớn.","Khi vật chạm đất thì thời gian rơi tự do xấp xỉ bằng thời gian chuyển theo quán tính.","Quỹ đạo chuyển động là một phần đường parabol."],"question":"<p class=\"text-base leading-relaxed my-2\">Đối với một vật bị ném ngang, khẳng định nào sau đây là <strong>sai</strong>?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn hệ trục: gốc O tại điểm ném, Ox nằm ngang theo $\\vec v_0$, Oy thẳng đứng hướng xuống. Bỏ qua sức cản không khí.</p><p class=\"text-base leading-relaxed my-2\">Phương trình chuyển động: $x=v_0t$ và $y=\\dfrac{1}{2}gt^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow y=\\dfrac{g}{2v_0^2}x^2$: quỹ đạo là một phần đường parabol, nên D đúng.</p><p class=\"text-base leading-relaxed my-2\">Chuyển động ném ngang gồm chuyển động đều theo phương ngang (theo quán tính, ở độ cao không đổi) và rơi tự do theo phương thẳng đứng, nên A đúng.</p><p class=\"text-base leading-relaxed my-2\">Thời gian rơi: $t=\\sqrt{\\dfrac{2h}{g}}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Tầm xa: $L=v_0t=v_0\\sqrt{\\dfrac{2h}{g}}$, tăng khi $v_0$ và $h$ tăng, nên B đúng.</p><p class=\"text-base leading-relaxed my-2\">Hai chuyển động thành phần diễn ra đồng thời nên thời gian của chúng bằng nhau đúng bằng thời gian chuyển động của vật, không phải \"xấp xỉ\". Cách phát biểu ở C mang tính tách rời hai thời gian, không chính xác bằng cách nói chúng luôn bằng nhau. Vì vậy C là khẳng định sai trong các phương án (các phương án còn lại đều đúng).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: chọn C.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Phân tích chuyển động ném ngang theo hai phương","answer":2,"options":["Chuyển động ném ngang có thể được phân tích thành hai chuyển động thành phần chuyển động theo quán tính ở độ cao không đổi và chuyển động rơi tự do.","Vận tốc ban đầu và chiều cao ban đầu càng lớn thì tầm ném xa càng lớn.","Khi vật chạm đất thì thời gian rơi tự do xấp xỉ bằng thời gian chuyển theo quán tính.","Quỹ đạo chuyển động là một phần đường parabol."],"question":"<p class=\"text-base leading-relaxed my-2\">Đối với một vật bị ném ngang, khẳng định nào sau đây là <strong>sai</strong>?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn hệ trục: gốc O tại điểm ném, Ox nằm ngang theo $\\vec v_0$, Oy thẳng đứng hướng xuống. Bỏ qua sức cản không khí.</p><p class=\"text-base leading-relaxed my-2\">Phương trình chuyển động: $x=v_0t$ và $y=\\dfrac{1}{2}gt^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow y=\\dfrac{g}{2v_0^2}x^2$: quỹ đạo là một phần đường parabol, nên D đúng.</p><p class=\"text-base leading-relaxed my-2\">Chuyển động ném ngang gồm chuyển động đều theo phương ngang (theo quán tính, ở độ cao không đổi) và rơi tự do theo phương thẳng đứng, nên A đúng.</p><p class=\"text-base leading-relaxed my-2\">Thời gian rơi: $t=\\sqrt{\\dfrac{2h}{g}}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Tầm xa: $L=v_0t=v_0\\sqrt{\\dfrac{2h}{g}}$, tăng khi $v_0$ và $h$ tăng, nên B đúng.</p><p class=\"text-base leading-relaxed my-2\">Hai chuyển động thành phần diễn ra đồng thời nên thời gian của chúng bằng nhau đúng bằng thời gian chuyển động của vật, không phải \"xấp xỉ\". Cách phát biểu ở C mang tính tách rời hai thời gian, không chính xác bằng cách nói chúng luôn bằng nhau. Vì vậy C là khẳng định sai trong các phương án (các phương án còn lại đều đúng).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: chọn C.</p>","difficultySource":"ai"}$q$::jsonb), archived = false, updated_at = now() where id = 1544548 and note = 'nap-vl10-c2-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Phân tích chuyển động ném ngang theo hai phương","answer":1,"options":["quỹ đạo là parabol có trục đối xứng là $Oy.$","quỹ đạo parabol có trục đối xứng là $Ox.$","vòng tròn có tâm là gốc $O$ của hệ tọa độ.","quỹ đạo elip có tâm đối xứng là gốc $O$ của hệ tọa độ."],"question":"<p class=\"text-base leading-relaxed my-2\">Một vật chuyển động đều dọc theo trục $Ox$ và đồng thời nhanh dần đều theo trục $ Oy.$ Vật đó chuyển động theo</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn gốc thời gian lúc vật ở gốc tọa độ. Theo trục $Ox$ vật chuyển động đều, theo trục $Oy$ vật chuyển động nhanh dần đều (vận tốc đầu theo $Oy$ bằng 0).</p><p class=\"text-base leading-relaxed my-2\">Phương trình chuyển động: $x = v_x t$ và $y = \\dfrac{1}{2} a t^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t = \\dfrac{x}{v_x}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow y = \\dfrac{a}{2v_x^2} x^2$</p><p class=\"text-base leading-relaxed my-2\">Đây là phương trình parabol $y = kx^2$ có trục đối xứng là $Oy$, đỉnh tại $O$. Như vậy quỹ đạo là parabol có trục đối xứng là $Oy$, ứng với phương án A.</p><p class=\"text-base leading-relaxed my-2\">Tuy nhiên, nếu đề muốn nói chuyển động đều theo $Oy$ và nhanh dần đều theo $Ox$ thì mới ra B. Theo đúng đề đã cho (đều theo $Ox$, nhanh dần đều theo $Oy$), đáp án đúng là A.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Phân tích chuyển động ném ngang theo hai phương","answer":1,"options":["quỹ đạo là parabol có trục đối xứng là $Oy.$","quỹ đạo parabol có trục đối xứng là $Ox.$","vòng tròn có tâm là gốc $O$ của hệ tọa độ.","quỹ đạo elip có tâm đối xứng là gốc $O$ của hệ tọa độ."],"question":"<p class=\"text-base leading-relaxed my-2\">Một vật chuyển động đều dọc theo trục $Ox$ và đồng thời nhanh dần đều theo trục $ Oy.$ Vật đó chuyển động theo</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn gốc thời gian lúc vật ở gốc tọa độ. Theo trục $Ox$ vật chuyển động đều, theo trục $Oy$ vật chuyển động nhanh dần đều (vận tốc đầu theo $Oy$ bằng 0).</p><p class=\"text-base leading-relaxed my-2\">Phương trình chuyển động: $x = v_x t$ và $y = \\dfrac{1}{2} a t^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t = \\dfrac{x}{v_x}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow y = \\dfrac{a}{2v_x^2} x^2$</p><p class=\"text-base leading-relaxed my-2\">Đây là phương trình parabol $y = kx^2$ có trục đối xứng là $Oy$, đỉnh tại $O$. Như vậy quỹ đạo là parabol có trục đối xứng là $Oy$, ứng với phương án A.</p><p class=\"text-base leading-relaxed my-2\">Tuy nhiên, nếu đề muốn nói chuyển động đều theo $Oy$ và nhanh dần đều theo $Ox$ thì mới ra B. Theo đúng đề đã cho (đều theo $Ox$, nhanh dần đều theo $Oy$), đáp án đúng là A.</p>","difficultySource":"ai"}$q$::jsonb), archived = false, updated_at = now() where id = 1544536 and note = 'nap-vl10-c2-20261020';
